#include <vector>
using namespace std;

int N, M, Q, p, r, a;
vector<int> prv, nxt;

int main() {
    cin >> N >> M >> Q;
    prv.resize(N);
    nxt.resize(N);

    // Optimized initialization of prv and nxt
    for (int i = 0; i < N; i++) {
        prv[i] = (i == 0) ? N - 1 : i - 1; // Previous element
        nxt[i] = (i + 1) % N; // Next element
    }

    for (int i = 0; i < M; i++) {
        cin >> a;
        for (int j = 0; j < a; j++) p = a % 2 ? prv[p] : nxt[p];
        nxt[prv[p]] = nxt[p], prv[nxt[p]] = prv[p];
        r = nxt[p], prv[p] = nxt[p] = -1, p = r;
    }

    for (int i = 0; i < Q; i++) cin >> a, cout << (prv[a] != -1 ? 1 : 0) << endl;
    return 0;
}

